european_countries_with_manufacturers = car_maker.WHERE(
    car_maker.country_join.continent_join.continent == "europe"
).CALCULATE(
    # Make the country name available for partitioning and final selection
    country_name_var=car_maker.country_join.countryname
).PARTITION(
    name="country_groups", by=country_name_var # Group by the country name
).CALCULATE(
    # Within each country group, count the number of car makers (records in this partition)
    # The 'country_name_var' is accessible here as it was part of the 'by' clause
    country_name=country_name_var,
    num_manufacturers=COUNT(car_maker) # COUNT the car makers in the current partition
).WHERE(
    num_manufacturers >= 3 # Filter for countries with at least 3 manufacturers
).CALCULATE(
    country_name=country_name # Select only the country name
)

