# Step 1: Calculate the maximum enrollment value across all colleges in the database.
# The 'max_enr_val' will be made available to subsequent chained operations.
states_with_colleges_less_than_others = GRAPH.CALCULATE(
    max_enr_val=MAX(colleges.enr)
).colleges.WHERE( # Access the 'colleges' collection, making 'max_enr_val' accessible in this context
    colleges.enr < max_enr_val # Filter colleges where enrollment is less than the global maximum
).PARTITION(
    name="states_group",
    by=colleges.state # Group the filtered colleges by their state to find unique states
).CALCULATE(
    state=colleges.state # Select the distinct state from each group, naming the output column 'state'
)

