    name == 'Safari'
).CALCULATE(
    id=id,
    market_share=market_share
)

qualified_medicines = medicines.CALCULATE(
    medicine_id=id,
    medicine_trade_name=Trade_Name,  # Corrected casing for Trade_Name based on schema
    num_interactions=COUNT(medicine_enzyme_interactions) # Count the plural sub-collection directly
).WHERE(
    num_interactions >= 3
).CALCULATE(
    id=medicine_id,
    trade_name=medicine_trade_name
)

last_staff_departure_date_query = GRAPH.CALCULATE(
    date_to=MAX(Project_Staff.date_to)
)

cheapest_catalog_level_name = product_catalog.catalog_content.TOP_K(
    1, by=price_in_dollars.ASC()
).SINGULAR().CALCULATE(
    # Access the catalog_structure relationship and get the catalog_level_name
    level_name=catalog_structure.catalog_level_name
)

GRAPH.CALCULATE(
    transcript_date=MAX(Transcripts.transcript_date)
)

result = GRAPH.CALCULATE(
    max_mpg=MAX(cars_datas.WHERE((cars_datas.cylinders == 8) | (cars_datas.year < 1980)).CALCULATE(mpg_numeric=DECIMAL(cars_datas.mpg)).mpg_numeric)
)
